place_text {space: "C-101", position: [15.8, 8.0], content: "N 90°00'00\" E 1405.27'", height: 0.1, layer: "rd_LAYOUT-NOTE-anno"}
place_text {space: "C-101", position: [17.5, 14.0], content: "N 90°00'00\" E 1405.27'", height: 0.12, layer: "rd_LAYOUT-NOTE-anno"}
place_text {space: "C-102", position: [18.2, 13.0], content: "N 71°33'54\" E 1240.36'", height: 0.12, layer: "rd_LAYOUT-NOTE-anno"}
place_text {space: "C-103", position: [18.0, 16.5], content: "N 90°00'00\" E 1353.95'", height: 0.12, layer: "rd_LAYOUT-NOTE-anno"}
